INSERT INTO public.embedding_chunks VALUES ('523a4a66e3cb78e3c464d4c9a81c10c5204d7c636a73c8ce873e8e39d393ec13', '12703b49f2fbb0cf059d48285e33b8f841595159e671517ac02129957e3ef048', 0, '**Kontekst Małopolski:** przysiółek w Pieninach. Mieszkańcy odległego przysiółka czują się odcięci od życia kulturalnego regionu. Brak połączeń autobusowych w weekendy utrudnia wyjazd na lokalne wydarzenia, do kina lub ośrodka kultury. Ludzie zamykają się w domach, tęskniąc za wspólnym spędzaniem czasu i udziałem w spotkaniach społeczności.', '24063ed1e116f435d33e9c5522159e530fe8419f2d0e8d2f6a8833d075b83e46', '[-0.0242126,0.026696166,-0.20554999,0.0028232113,-0.034604695,-0.036416523,-0.013190492,0.012805192,0.011992513,0.0094230175,-0.059297297,-0.034610126,0.09423083,0.008874028,-0.021518739,-0.072150454,-0.06380617,-0.014518405,-0.042909093,0.05820431,-0.015923275,0.029363694,0.032639675,-0.023450468,0.054326948,-0.0071876757,0.10290354,0.0003646168,-0.02310072,-0.049076937,0.021682661,-0.03992714,-0.037595704,-0.04541851,-0.017868375,-0.084961206,0.06225462,-0.015902327,0.0014862625,0.0036930663,0.032987032,-0.053562153,0.11372831,-0.025981542,0.080443464,-0.045231137,-0.014434832,0.023613792,0.045299172,0.011928514,0.018098684,-0.04269426,0.028947648,-0.08941782,0.05510325,0.02034786,0.01405036,0.0022336578,0.07704634,4.9518376e-06,0.08549461,0.09886016,-0.08086069,0.07757675,0.011766746,-0.03523957,-0.06868867,0.10978062,-0.01139688,-0.08376787,0.060456168,-0.020954061,0.06839934,-0.04081415,-0.022147162,-0.011644642,-0.03668334,-0.04351771,0.04693613,0.007115863,0.06744011,0.055201836,0.07721626,0.022672612,-0.034976624,0.016727818,-0.008455063,-0.020998104,-0.020919226,0.05884119,0.00276855,-0.0007870346,0.050411317,0.044151157,-0.08305378,0.02630257,-0.016213804,0.05747509,-0.024250193,-0.04990759,-0.020071669,-0.030581284,0.00931708,-0.014643892,0.067246385,-0.018296922,-0.023168012,0.024446625,-0.031930182,0.007708962,-0.023547305,0.08656599,-0.033962302,-0.0066149943,0.0206