INSERT INTO public.embedding_chunks VALUES ('f6e012c156b5f3335ec40d00b31d539456c422fdb2254b3ff69cda539279af3a', '12703b49f2fbb0cf059d48285e33b8f841595159e671517ac02129957e3ef048', 0, '**Kontekst Małopolski:** okolice Kalwarii Zebrzydowskiej. Starsza osoba mieszkająca w domu z ogrodem nie ma już siły na grabienie liści, pielenie grządek i przycinanie gałęzi. Widok zaniedbanego obejścia wywołuje bezradność i smutek. Ciężka praca fizyczna przekracza obecne możliwości, a brakuje doraźnego wsparcia w prostych pracach wokół domu.', 'bb9d58ad9b2e2333a5c1532ac8392dd8677a3e0b4b8a54ac51b3d072b0a5a780', '[-0.04462261,0.04012661,-0.17292883,-0.0028601189,-0.05880369,-0.0021803116,-0.011199993,-0.020611446,0.01460595,0.022872653,-0.081169695,0.03491588,0.12267703,-0.026612606,0.008587174,-0.02111564,-0.023454333,-0.059974957,-0.10120117,0.050654646,-0.021332081,0.010108881,0.027756717,-0.0024953187,0.062032994,-0.0089796735,0.074940406,0.007876539,-0.03813308,-0.016625563,0.032352734,0.028565425,-0.019191833,-0.029056637,0.03273985,-0.08372798,0.07143491,0.010589893,-0.008254119,-0.02546804,-0.009204034,-0.061339237,0.11507823,-0.06356887,0.059555337,-0.05492198,0.02511167,0.050630305,0.04699477,0.01858505,0.06409437,-0.014768856,0.11164827,-0.03840018,0.080651365,0.021388166,0.022359895,-0.029701438,0.050821453,-0.028498318,0.07326334,0.08584587,-0.060227077,0.04430074,-0.021086926,-0.05799285,-0.05954946,0.077801704,-0.003927085,-0.094671085,0.1046519,0.017471887,0.062796935,-0.041824456,-0.060332645,-0.011970446,-0.042342313,-0.08017713,0.038367815,-0.01540604,0.08592362,0.005501377,0.07811825,0.0207883,0.010789559,0.056138437,0.004308471,0.032127563,-0.012001754,0.04697007,0.042615917,-0.015706155,0.03622723,0.06782257,-0.05917079,0.040784474,-0.0334156,0.023780202,-0.026770784,-0.07033881,-0.01039323,-0.021869028,0.08449403,-0.009457903,0.06563972,0.043730456,0.018700276,0.03257296,-0.0012115187,-0.0062046126,-0.0062696347,0.060618196,-0.013595704,-0.04195579,0.022399928,-0