INSERT INTO public.embedding_chunks VALUES ('184a7945e90dd781315d33f79bebb11532680892d247cef61f718e4b519bbba9', '12703b49f2fbb0cf059d48285e33b8f841595159e671517ac02129957e3ef048', 0, '**Kontekst Małopolski:** mała miejscowość w Beskidach. Starsza osoba mieszkająca samotnie w górzystej okolicy ma trudność z samodzielnym dotarciem do najbliższego sklepu. Zimą strome podejścia utrudniają zdobycie świeżej żywności i leków. Brakuje stałego, sąsiedzkiego wsparcia w prostych codziennych obowiązkach, co prowadzi do poczucia izolacji i rezygnacji z dbania o podstawowe potrzeby.', '3891ce3dcd75bed4d5db762d71e50a98d5c1fdeb62555123e463d3722f74dabb', '[-0.037966847,0.016307926,-0.16266464,-0.03548281,-0.014387635,-0.034901995,-0.029903483,-0.026999826,0.008305949,0.04885401,-0.09031102,-0.020634206,0.11625047,-0.019690793,-0.039726116,-0.04108798,-0.028786678,-0.061820593,-0.082437,0.08069946,-0.04068137,0.032479133,0.03170656,-0.03545338,0.03914775,0.046905264,0.08967783,0.005193531,-0.00075332995,-0.01583153,0.047965456,0.0019340597,0.0066275294,-0.034943305,0.025464863,-0.09823649,0.04142924,0.024652846,0.007861423,-0.026179131,0.035321254,-0.031385213,0.0770843,-0.07516398,0.05802067,-0.04722454,0.011214029,0.017664874,0.06234676,-0.03457425,0.04534342,0.015905323,0.060687013,-0.0520356,0.061460525,0.022308776,0.062997974,-0.013555586,0.03841845,-0.0041988334,0.071938396,0.093536936,-0.06627955,0.03065799,-0.01329277,-0.009012792,-0.072323516,0.0877632,-0.019529417,-0.072617956,0.09524534,-0.008805232,0.09412216,-0.013152757,-0.03344328,-0.04003994,-0.05744781,-0.03995344,0.023343885,-0.014431414,0.07848244,-0.011243131,0.10410079,0.003049554,0.0027797758,0.01914578,-0.03605934,0.013562675,-0.02099567,0.07649692,0.0041712644,-0.0008113109,0.03700422,0.024427712,-0.04174155,0.045596793,-0.020089205,0.052786607,-0.0517649,-0.062494297,-0.013240963,-0.028479116,0.035513643,-0.019133644,0.07898705,0.040590215,0.01886782,0.013848537,-0.007822399,-0.027802896,0.01938014,0.08315963